package com.yeyamo_mobile.api.recommendation_service.domain;public record RecommendationContext(Double latitude,Double longitude){public RecommendationContext{if((latitude==null)!=(longitude==null))throw new IllegalArgumentException("lat and lng are required together");if(latitude!=null&&(latitude < -90||latitude > 90||longitude < -180||longitude > 180))throw new IllegalArgumentException("invalid coordinates");}}
